const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const route=String(input.route??'').toLowerCase(); const mode=String(input.message_mode??'').toLowerCase();
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const attempts=Number(input.reengagement_attempts??input.attempts??0); const nextAttempt=Number(input.next_reengagement_attempt??attempts+1);
const idempotencyKey=String(input.idempotency_key??'').trim();
const seller=input.seller??{}; const phone=String(seller.phone??input.recipient_phone??input.seller_phone??'').trim(); const email=String(seller.email??input.recipient_email??input.seller_email??'').trim();
const context=input.seller_context??input.motivation??input.conversation_context??null;
let status='needs_review'; let dispatchMode='none'; let nextWorkflow='WF-346'; let reason='Message generation requires review.';
if(dnc){status='dnc_blocked';nextWorkflow='WF-126';reason='DNC protection prevents message generation or dispatch.';}
else if(blockers.length){status='blocked';nextWorkflow='WF-126';reason='Active blocker prevents outbound communication.';}
else if(!dealId||!leadId||!propertyId||(!phone&&!email)){status='incomplete';nextWorkflow='WF-346';reason='Required deal identity or seller contact is missing.';}
else if(!idempotencyKey){status='invalid_idempotency';nextWorkflow='WF-346';reason='Deterministic dispatch idempotency key is missing.';}
else if(route!=='message_ready'){status='not_authorized';nextWorkflow='WF-346';reason='Input is not authorized for autonomous message generation.';}
else if(attempts>=3){status='max_attempts_reached';nextWorkflow='WF-126';reason='Maximum re-engagement attempts reached.';}
else if(mode==='sms'&&phone){status='message_ready';dispatchMode='sms';nextWorkflow='WF-263';reason='SMS re-engagement message generation is authorized.';}
else if(mode==='email'&&email){status='message_ready';dispatchMode='email';nextWorkflow='WF-263';reason='Email re-engagement message generation is authorized.';}
else if(phone){status='message_ready';dispatchMode='sms';nextWorkflow='WF-263';reason='SMS is available as the preferred provider-agnostic channel.';}
else if(email){status='message_ready';dispatchMode='email';nextWorkflow='WF-263';reason='Email is available as the fallback channel.';}
const messageBrief={purpose:'seller_reengagement',channel:dispatchMode,tone:'concise, respectful, non-pressuring',seller_context:context,attempt_number:nextAttempt,do_not_contact:dnc,deal_id:dealId,lead_id:leadId,property_id:propertyId};
const activity={activity_type:'seller_reengagement_message_generation',subject:'WF-347 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status,dispatch_mode:dispatchMode,attempt_number:nextAttempt,idempotency_key:idempotencyKey,recipient_phone:phone,recipient_email:email,message_brief:messageBrief,dnc,blockers,reason,next_workflow:nextWorkflow};
return [{json:{...input,wf_id:'WF-347',status,dispatch_mode:dispatchMode,message_brief:messageBrief,next_workflow:nextWorkflow,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
